import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** One existing arena dispatcher port and one original NPC body copied with explicit scene adapters. */
public final class BattleControlledCancellationMethods {
 static final String P="local/lito381/server/",N=P+"NativeBattleControlledCancellation",PC=P+"ClientSession",A=P+"NativeCancellationMaterialAction",AREA=P+"NativeAreaMaterialAction",CTX=AREA+"$Context";
 static MethodNode method(ClassNode c,String name){return c.methods.stream().filter(m->m.name.equals(name)).findFirst().orElseThrow();}
 static void dispatcher(ClassNode c){var old=method(c,"battle");old.name="nativeControlledOriginalBattle";var m=new MethodNode(old.access,"battle",old.desc,old.signature,old.exceptions.toArray(String[]::new));for(int i=0;i<4;i++)m.instructions.add(new VarInsnNode(ALOAD,i));m.instructions.add(new MethodInsnNode(INVOKESTATIC,N,"cast",old.desc.replace(")V",")Z"),false));var fallback=new LabelNode();m.instructions.add(new JumpInsnNode(IFEQ,fallback));m.instructions.add(new InsnNode(RETURN));m.instructions.add(fallback);m.instructions.add(new FrameNode(F_SAME,0,null,0,null));for(int i=0;i<4;i++)m.instructions.add(new VarInsnNode(ALOAD,i));m.instructions.add(new MethodInsnNode(INVOKESTATIC,c.name,old.name,old.desc,false));m.instructions.add(new InsnNode(RETURN));c.methods.add(m);}
 static void capture(ClassNode c){var old=method(c,"captureOutput");old.name="nativeBattleControlledOriginalCaptureOutput";var m=new MethodNode(old.access,"captureOutput",old.desc,old.signature,old.exceptions.toArray(String[]::new));m.instructions.add(new MethodInsnNode(INVOKESTATIC,N,"active","()Z",false));var prior=new LabelNode();m.instructions.add(new JumpInsnNode(IFEQ,prior));for(int i=0;i<3;i++)m.instructions.add(new VarInsnNode(ALOAD,i));m.instructions.add(new MethodInsnNode(INVOKESTATIC,N,"captureOutput",old.desc,false));m.instructions.add(new InsnNode(IRETURN));m.instructions.add(prior);m.instructions.add(new FrameNode(F_SAME,0,null,0,null));for(int i=0;i<3;i++)m.instructions.add(new VarInsnNode(ALOAD,i));m.instructions.add(new MethodInsnNode(INVOKESTATIC,c.name,old.name,old.desc,false));m.instructions.add(new InsnNode(IRETURN));c.methods.add(m);}
 static void frame(ClassNode c){var m=method(c,"nativeStaticOriginalFrame");var prefix=new InsnList();prefix.add(new VarInsnNode(ALOAD,0));prefix.add(new VarInsnNode(ALOAD,1));prefix.add(new MethodInsnNode(INVOKESTATIC,N,"allowFrame","(L"+PC+";[B)Z",false));var allowed=new LabelNode();prefix.add(new JumpInsnNode(IFNE,allowed));prefix.add(new InsnNode(RETURN));prefix.add(allowed);prefix.add(new FrameNode(F_NEW,3,new Object[]{PC,"[B","java/lang/String"},0,null));m.instructions.insert(prefix);}
 static Map<String,Integer> ports(MethodNode m){var counts=new TreeMap<String,Integer>();for(var node:m.instructions.toArray()){
  if(node instanceof FieldInsnNode f&&f.owner.equals(PC+"$Phase")&&f.name.equals("WORLD")){f.name="BATTLE";counts.merge("phase",1,Integer::sum);}
  else if(node instanceof MethodInsnNode call){String name=null;if(call.owner.equals(PC))name=switch(call.name){case "sameClassicWorldMap"->"sameRoom";case "admitClassicWorldSpellFamily"->"family";case "classicWorldMembers"->"members";case "removeClassicWorldFreezeEffectAndPublish"->"freeze";case "removeClassicWorldBoneBreakEffectAndPublish"->"bone";default->null;};else if(call.owner.equals(P+"GameHub")&&call.name.equals("cancelClassicWorldPatience"))name="patience";if(name!=null){call.desc="(L"+call.owner+";"+call.desc.substring(1);call.owner=N;call.name=name;call.setOpcode(INVOKESTATIC);call.itf=false;counts.merge(name,1,Integer::sum);}}
  else if(node instanceof InvokeDynamicInsnNode indy&&indy.desc.equals("(II)Ljava/util/function/Predicate;")&&counts.getOrDefault("memberFilter",0)==0){m.instructions.set(indy,new MethodInsnNode(INVOKESTATIC,N,"memberFilter",indy.desc,false));counts.merge("memberFilter",1,Integer::sum);}
 }return counts;}
 static void player(ClassNode c){var old=method(c,"nativeMaterialWorldNpcCancellationBody");var copy=new MethodNode(old.access,"nativeBattleControlledCancellationBody",old.desc,old.signature,old.exceptions.toArray(String[]::new));old.accept(copy);var counts=ports(copy);var expected=Map.of("phase",3,"sameRoom",2,"family",1,"members",1,"freeze",1,"bone",1,"patience",1,"memberFilter",1);if(!counts.equals(expected))throw new AssertionError("original NPC scene ports "+counts);c.methods.add(copy);System.out.println(counts);}
 public static void main(String[]a)throws Exception{try(var jar=new JarFile(a[1])){for(String name:List.of(PC,A,AREA,CTX)){var c=FreezeAcceptedMethods.read(jar,name);if(name.equals(PC)){player(c);frame(c);}else if(name.equals(A))dispatcher(c);else if(name.equals(AREA))capture(c);else c.fields.add(new FieldNode(ACC_VOLATILE,"nativeBattleControlledCancellationScope","Ljava/lang/Object;",null,null));byte[] initial=FreezeAcceptedMethods.bytes(c,false);var canonical=new ClassNode();new ClassReader(initial).accept(canonical,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);byte[] bytes=FreezeAcceptedMethods.bytes(canonical,false);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(name+".class");Files.createDirectories(p.getParent());Files.write(p,bytes);}else try(var out=new JarFile(a[2])){if(!Arrays.equals(bytes,FreezeAcceptedMethods.bytes(FreezeAcceptedMethods.read(out,name),false)))throw new AssertionError(name);}}}System.out.println("PASS arena controlled cancellation exact body, bounded context and final native frame projection");}
}
